import math
from typing import List

class Router:
    EARTH_KM = 6371

    def __init__(self):
        self.dc = {}   # name -> dict(lat, lon, cap, load, healthy)

    def register(self, name: str, lat: float, lon: float, cap: int) -> str:
        if not (-90 <= lat <= 90) or not (-180 <= lon <= 180) or cap < 0:
            return "ERROR: invalid"
        if name in self.dc:
            return "ERROR: duplicate"
        self.dc[name] = {"lat": lat, "lon": lon, "cap": cap, "load": 0, "healthy": True}
        return "SUCCESS"

    def set_healthy(self, name: str, flag: bool) -> str:
        if name not in self.dc:
            return "ERROR: not found"
        self.dc[name]["healthy"] = flag
        return "SUCCESS"

    @classmethod
    def distance(cls, lat1, lon1, lat2, lon2) -> int:
        p1, p2 = math.radians(lat1), math.radians(lat2)
        dp, dl = math.radians(lat2 - lat1), math.radians(lon2 - lon1)
        a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
        a = min(1.0, max(0.0, a))                    # 防浮点误差让 sqrt(1-a) 变成负数开方
        c = 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))
        return int(cls.EARTH_KM * c)                 # 截断取整

    def route(self, lat: float, lon: float) -> str:
        best = None
        for name, d in self.dc.items():
            if d["healthy"] and d["load"] < d["cap"]:
                key = (self.distance(lat, lon, d["lat"], d["lon"]), name)
                if best is None or key < best:
                    best = key
        if best is None:
            return "ERROR: no capacity"
        self.dc[best[1]]["load"] += 1
        return f"SUCCESS {best[1]}"


def process(commands: List[str]) -> List[str]:
    r, out = Router(), []
    for cmd in commands:
        p = cmd.split()
        if p[0] == "REGISTER":
            out.append(r.register(p[1], float(p[2]), float(p[3]), int(p[4])))
        elif p[0] == "SET_HEALTHY":
            out.append(r.set_healthy(p[1], p[2].lower() == "true"))
        elif p[0] == "DISTANCE":
            out.append(str(Router.distance(*map(float, p[1:5]))))
        elif p[0] == "ROUTE":
            out.append(r.route(float(p[1]), float(p[2])))
    return out
